+class ContactForm {
+    constructor() {
+        this.form = document.getElementById('contactForm');
+        this.successMessage = document.getElementById('successMessage');
+        this.fields = {
+            fullName: {
+                input: document.getElementById('fullName'),
+                errorElement: document.getElementById('fullNameError'),
+                validators: [
+                    { validate: (val) => val.trim().length > 0, message: 'Full name is required' },
+                    { validate: (val) => val.trim().length >= 2, message: 'Full name must be at least 2 characters' }
+                ]
+            },
+            email: {
+                input: document.getElementById('email'),
+                errorElement: document.getElementById('emailError'),
+                validators: [
+                    { validate: (val) => val.trim().length > 0, message: 'Email address is required' },
+                    { validate: (val) => this.isValidEmail(val), message: 'Please enter a valid email address' }
+                ]
+            },
+            phone: {
+                input: document.getElementById('phone'),
+                errorElement: document.getElementById('phoneError'),
+                validators: [
+                    { validate: (val) => val.trim().length === 0 || this.isValidPhone(val), message: 'Please enter a valid phone number' }
+                ]
+            }
+        };
+
+        this.init();
+    }
+
+    init() {
+        this.form.addEventListener('submit', (e) => this.handleSubmit(e));
+        
+        Object.values(this.fields).forEach(field => {
+            field.input.addEventListener('blur', () => this.validateField(field));
+            field.input.addEventListener('input', () => {
+                if (field.errorElement.textContent) {
+                    this.validateField(field);
+                }
+            });
+        });
+    }
+
+    isValidEmail(email) {
+        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+        return emailRegex.test(email.trim());
+    }
+
+    isValidPhone(phone) {
+        const cleanPhone = phone.replace(/\D/g, '');
+        return cleanPhone.length === 10 || cleanPhone.length === 11;
+    }
+
+    validateField(field) {
+        const value = field.input.value;
+        let errorMessage = '';
+
+        for (const validator of field.validators) {
+            if (!validator.validate(value)) {
+                errorMessage = validator.message;
+                break;
+            }
+        }
+
+        field.errorElement.textContent = errorMessage;
+        field.input.setAttribute('aria-invalid', errorMessage ? 'true' : 'false');
+
+        return !errorMessage;
+    }
+
+    validateForm() {
+        let isValid = true;
+
+        Object.values(this.fields).forEach(field => {
+            if (!this.validateField(field)) {
+                isValid = false;
+            }
+        });
+
+        return isValid;
+    }
+
+    handleSubmit(e) {
+        e.preventDefault();
+
+        if (!this.validateForm()) {
+            const firstInvalidField = Object.values(this.fields).find(
+                field => field.input.getAttribute('aria-invalid') === 'true'
+            );
+            
+            if (firstInvalidField) {
+                firstInvalidField.input.focus();
+            }
+            return;
+        }
+
+        const formData = {
+            fullName: this.fields.fullName.input.value.trim(),
+            email: this.fields.email.input.value.trim(),
+            phone: this.fields.phone.input.value.trim() || null
+        };
+
+        console.log('Form submitted:', formData);
+
+        this.form.style.display = 'none';
+        this.successMessage.style.display = 'block';
+
+        setTimeout(() => {
+            this.form.reset();
+            this.form.style.display = 'flex';
+            this.successMessage.style.display = 'none';
+            
+            Object.values(this.fields).forEach(field => {
+                field.errorElement.textContent = '';
+                field.input.setAttribute('aria-invalid', 'false');
+            });
+
+            this.fields.fullName.input.focus();
+        }, 3000);
+    }
+}
+
+document.addEventListener('DOMContentLoaded', () => {
+    new ContactForm();
+});
+
